1. using Microsoft.VisualStudio.TestTools.UnitTesting;
2. using Store;
3. 
4. namespace Store.Tests;
5. 
6. [TestClass]
7. public sealed class ShoppingCartTests
8. {
9.     private ShoppingCart _cart = null!;
10. 
11.     [TestInitialize]
12.     public void Setup() => _cart = new ShoppingCart();
13. 
14.     // ── AddItem ──────────────────────────────────────────────
15. 
16.     [TestMethod]
17.     public void AddItem_SingleItem_AppearsInCart()
18.     {
19.         _cart.AddItem("SKU-1", 2, 9.99m);
20. 
21.         Assert.AreEqual(1, _cart.Items.Count);
22.         Assert.AreEqual(2, _cart.Items["SKU-1"].Quantity);
23.         Assert.AreEqual(9.99m, _cart.Items["SKU-1"].Price);
24.     }
25. 
26.     [TestMethod]
27.     public void AddItem_SameSkuTwice_QuantitiesAccumulate()
28.     {
29.         _cart.AddItem("SKU-1", 1, 5.00m);
30.         _cart.AddItem("SKU-1", 3, 5.00m);
31. 
32.         Assert.AreEqual(1, _cart.Items.Count);
33.         Assert.AreEqual(4, _cart.Items["SKU-1"].Quantity);
34.     }
35. 
36.     [TestMethod]
37.     public void AddItem_MultipleSkus_AllAppearInCart()
38.     {
39.         _cart.AddItem("A", 1, 1.00m);
40.         _cart.AddItem("B", 2, 2.00m);
41. 
42.         Assert.AreEqual(2, _cart.Items.Count);
43.     }
44. 
45.     [TestMethod]
46.     public void AddItem_NullSku_Throws() =>
47.         Assert.ThrowsException<ArgumentNullException>(() => _cart.AddItem(null!, 1, 1.00m));
48. 
49.     [TestMethod]
50.     public void AddItem_EmptySku_Throws() =>
51.         Assert.ThrowsException<ArgumentException>(() => _cart.AddItem("", 1, 1.00m));
52. 
53.     [TestMethod]
54.     public void AddItem_WhitespaceSku_Throws() =>
55.         Assert.ThrowsException<ArgumentException>(() => _cart.AddItem("   ", 1, 1.00m));
56. 
57.     [TestMethod]
58.     public void AddItem_ZeroQuantity_Throws() =>
59.         Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 0, 1.00m));
60. 
61.     [TestMethod]
62.     public void AddItem_NegativeQuantity_Throws() =>
63.         Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", -1, 1.00m));
64. 
65.     [TestMethod]
66.     public void AddItem_NegativePrice_Throws() =>
67.         Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 1, -0.01m));
68. 
69.     [TestMethod]
70.     public void AddItem_ZeroPrice_Allowed()
71.     {
72.         _cart.AddItem("FREEBIE", 1, 0m);
73.         Assert.AreEqual(0m, _cart.Items["FREEBIE"].Price);
74.     }
75. 
76.     // ── RemoveItem ───────────────────────────────────────────
77. 
78.     [TestMethod]
79.     public void RemoveItem_ExistingItem_RemovedFromCart()
80.     {
81.         _cart.AddItem("SKU-1", 1, 5.00m);
82.         _cart.RemoveItem("SKU-1");
83. 
84.         Assert.AreEqual(0, _cart.Items.Count);
85.     }
86. 
87.     [TestMethod]
88.     public void RemoveItem_NonExistentSku_Throws() =>
89.         Assert.ThrowsException<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
90. 
91.     [TestMethod]
92.     public void RemoveItem_NullSku_Throws() =>
93.         Assert.ThrowsException<ArgumentNullException>(() => _cart.RemoveItem(null!));
94. 
95.     [TestMethod]
96.     public void RemoveItem_EmptySku_Throws() =>
97.         Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(""));
98. 
99.     // ── CalculateTotal ───────────────────────────────────────
100. 
101.     [TestMethod]
102.     public void CalculateTotal_EmptyCart_ReturnsZero()
103.     {
104.         Assert.AreEqual(0m, _cart.CalculateTotal());
105.     }
106. 
107.     [TestMethod]
108.     public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
109.     {
110.         _cart.AddItem("A", 3, 10.00m);
111.         Assert.AreEqual(30.00m, _cart.CalculateTotal());
112.     }
113. 
114.     [TestMethod]
115.     public void CalculateTotal_MultipleItems_SumsCorrectly()
116.     {
117.         _cart.AddItem("A", 2, 5.50m);  // 11.00
118.         _cart.AddItem("B", 1, 3.25m);  //  3.25
119. 
120.         Assert.AreEqual(14.25m, _cart.CalculateTotal());
121.     }
122. 
123.     [TestMethod]
124.     public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
125.     {
126.         _cart.AddItem("A", 1, 10.00m);
127.         _cart.AddItem("B", 1, 20.00m);
128.         _cart.RemoveItem("A");
129. 
130.         Assert.AreEqual(20.00m, _cart.CalculateTotal());
131.     }
132. 
133.     // ── ApplyCoupon ──────────────────────────────────────────
134. 
135.     [TestMethod]
136.     public void ApplyCoupon_Save10_Applies10PercentDiscount()
137.     {
138.         _cart.AddItem("A", 1, 100.00m);
139.         _cart.ApplyCoupon("SAVE10");
140. 
141.         Assert.AreEqual(90.00m, _cart.CalculateTotal());
142.         Assert.AreEqual("SAVE10", _cart.AppliedCoupon);
143.     }
144. 
145.     [TestMethod]
146.     public void ApplyCoupon_Save20_Applies20PercentDiscount()
147.     {
148.         _cart.AddItem("A", 1, 50.00m);
149.         _cart.ApplyCoupon("SAVE20");
150. 
151.         Assert.AreEqual(40.00m, _cart.CalculateTotal());
152.     }
153. 
154.     [TestMethod]
155.     public void ApplyCoupon_Half_Applies50PercentDiscount()
156.     {
157.         _cart.AddItem("A", 2, 30.00m);
158.         _cart.ApplyCoupon("HALF");
159. 
160.         Assert.AreEqual(30.00m, _cart.CalculateTotal());
161.     }
162. 
163.     [TestMethod]
164.     public void ApplyCoupon_CaseInsensitive()
165.     {
166.         _cart.AddItem("A", 1, 100.00m);
167.         _cart.ApplyCoupon("save10");
168. 
169.         Assert.AreEqual(90.00m, _cart.CalculateTotal());
170.     }
171. 
172.     [TestMethod]
173.     public void ApplyCoupon_UnknownCode_Throws() =>
174.         Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
175. 
176.     [TestMethod]
177.     public void ApplyCoupon_NullCode_Throws() =>
178.         Assert.ThrowsException<ArgumentNullException>(() => _cart.ApplyCoupon(null!));
179. 
180.     [TestMethod]
181.     public void ApplyCoupon_EmptyCode_Throws() =>
182.         Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(""));
183. 
184.     [TestMethod]
185.     public void ApplyCoupon_ReplacePreviousCoupon()
186.     {
187.         _cart.AddItem("A", 1, 100.00m);
188.         _cart.ApplyCoupon("SAVE10");
189.         _cart.ApplyCoupon("SAVE20");
190. 
191.         Assert.AreEqual(80.00m, _cart.CalculateTotal());
192.         Assert.AreEqual("SAVE20", _cart.AppliedCoupon);
193.     }
194. 
195.     [TestMethod]
196.     public void CalculateTotal_WithCoupon_RoundsCorrectly()
197.     {
198.         _cart.AddItem("A", 3, 3.33m);   // subtotal = 9.99
199.         _cart.ApplyCoupon("SAVE10");     // 9.99 * 0.90 = 8.991 → 8.99
200. 
201.         Assert.AreEqual(8.99m, _cart.CalculateTotal());
202.     }
203. 
204.     // ── Integration / edge scenarios ─────────────────────────
205. 
206.     [TestMethod]
207.     public void CalculateTotal_NoCoupon_ReturnsFullPrice()
208.     {
209.         _cart.AddItem("A", 1, 49.99m);
210.         Assert.IsNull(_cart.AppliedCoupon);
211.         Assert.AreEqual(49.99m, _cart.CalculateTotal());
212.     }
213. 
214.     [TestMethod]
215.     public void AddThenRemoveAllItems_TotalIsZero()
216.     {
217.         _cart.AddItem("A", 1, 10.00m);
218.         _cart.AddItem("B", 1, 20.00m);
219.         _cart.RemoveItem("A");
220.         _cart.RemoveItem("B");
221. 
222.         Assert.AreEqual(0m, _cart.CalculateTotal());
223.     }
224. }
